class Booking {
    protected final int nights;      // subclasses may read it directly

    Booking(int nights) {
        this.nights = nights;
    }
}

class RoomBooking extends Booking {
    private final double nightly;

    RoomBooking(int nights, double nightly) {
        super(nights);
        this.nightly = nightly;
    }

    double total() {
        return nights * nightly;     // no getter needed
    }
}

System.out.println(new RoomBooking(2, 90.0).total());   // 180.0

class Parent {
    static { System.out.println("1 parent static"); }
    { System.out.println("3 parent instance"); }
    Parent() { System.out.println("4 parent constructor"); }
}

class Child extends Parent {
    static { System.out.println("2 child static"); }
    { System.out.println("5 child instance"); }
    Child() {                                       // super() runs before this body
        System.out.println("6 child constructor");
    }
}

new Child();
// 1 parent static, 2 child static, 3 parent instance,
// 4 parent constructor, 5 child instance, 6 child constructor

class Booking {
    private final int nights;

    Booking(int nights) {
        if (nights < 1) {
            throw new IllegalArgumentException("nights must be at least 1");
        }
        this.nights = nights;
    }

    int getNights() { return nights; }
}

class RoomBooking extends Booking {
    private final double nightly;
    private final double discount;

    RoomBooking(int nights, double nightly) {
        this(nights, nightly, 0.0);      // chains to the constructor below
    }

    RoomBooking(int nights, double nightly, double discount) {
        super(nights);                   // the chain ends in a super call
        this.nightly = nightly;
        this.discount = discount;
    }

    double total() { return getNights() * nightly - discount; }
}

System.out.println(new RoomBooking(2, 90.0).total());          // 180.0
System.out.println(new RoomBooking(2, 90.0, 30.0).total());    // 150.0

abstract class ImportJob {
    // The skeleton is final: order, logging and counting cannot be changed.
    final void run(String path) {
        System.out.println("start " + path);
        int rows = parse(path);
        afterParse(rows);
        System.out.println("done " + rows + " rows");
    }

    abstract int parse(String path);          // required, every subclass answers

    void afterParse(int rows) { }             // optional hook, empty by default
}

class CsvImport extends ImportJob {
    @Override int parse(String path) { return 120; }

    @Override void afterParse(int rows) {
        System.out.println("indexing " + rows + " rows");
    }
}

class SilentImport extends ImportJob {
    @Override int parse(String path) { return 4; }
}

new CsvImport().run("bookings.csv");
new SilentImport().run("cities.csv");

interface Billable {
    double amount();

    default String label() { return "amount " + amount(); }
}

interface Auditable {
    String auditRef();

    default String label() { return "audit " + auditRef(); }
}

class InvoiceLine implements Billable, Auditable {
    @Override public double amount() { return 277.5; }

    @Override public String auditRef() { return "INV-7"; }

    // Without this override the class does not compile, and the error names
    // both interfaces.
    @Override
    public String label() {
        return Billable.super.label() + " / " + Auditable.super.label();
    }
}

System.out.println(new InvoiceLine().label());
// amount 277.5 / audit INV-7

interface Payable {
    double amount();

    static Payable of(double amount) {
        if (amount < 0) {
            throw new IllegalArgumentException("amount cannot be negative");
        }
        return () -> amount;        // one abstract method, so a lambda fits
    }

    static Payable free() {
        return of(0.0);
    }
}

Payable p = Payable.of(277.5);
System.out.println(p.amount());            // 277.5
System.out.println(Payable.free().amount());   // 0.0

