interface Receipt {
    double amount();

    default String line() {
        return "total " + money(amount());
    }

    default String depositLine() {
        return "deposit " + money(amount() * 0.3);
    }

    // Not part of the contract: no implementing class can call or override it.
    private String money(double value) {
        return String.format("%.2f EUR", value);
    }
}

class RoomCharge implements Receipt {
    @Override public double amount() { return 180.0; }
}

System.out.println(new RoomCharge().line());          // total 180.00 EUR
System.out.println(new RoomCharge().depositLine());   // deposit 54.00 EUR

sealed interface RatePlan permits Nightly, Flat, Corporate { }

record Nightly(double nightly) implements RatePlan { }   // records are final

final class Flat implements RatePlan {                   // branch closed
    private final double fee;

    Flat(double fee) { this.fee = fee; }

    double fee() { return fee; }
}

// non-sealed reopens the branch, so anyone may extend it:
non-sealed class Corporate implements RatePlan { }

class OverseasCorporate extends Corporate { }            // legal only for this reason

sealed interface RatePlan permits Nightly, Bundle { }

record Nightly(double nightly) implements RatePlan { }

record Bundle(int nights, double fee, boolean breakfast) implements RatePlan { }

double price(RatePlan plan) {
    return switch (plan) {
        case Nightly n -> n.nightly() * 3;

        // Record pattern: components bound directly. The guard filters this arm.
        case Bundle(int nights, double fee, boolean breakfast) when breakfast ->
                fee + 9.0 * nights;

        case Bundle b -> b.fee();
    };
}

System.out.println(price(new Nightly(92.5)));             // 277.5
System.out.println(price(new Bundle(3, 250.0, true)));   // 277.0
System.out.println(price(new Bundle(2, 250.0, false)));  // 250.0

interface RefundPolicy {
    double refund(double paid, int daysBeforeStart);
}

class TieredCancel implements RefundPolicy {
    @Override public double refund(double paid, int days) {
        if (days >= 7) return paid;
        if (days >= 2) return paid * 0.5;
        return 0.0;
    }
}

class Booking {
    private final double total;
    private final RefundPolicy policy;      // has-a, not is-a

    Booking(double total, RefundPolicy policy) {
        this.total = total;
        this.policy = policy;
    }

    double refund(int days) {
        return policy.refund(total, days);  // delegate, keep the rule outside
    }
}

System.out.println(new Booking(277.5, new TieredCancel()).refund(3));      // 138.75
System.out.println(new Booking(277.5, (paid, days) -> paid).refund(1));    // 277.5

class Booking {
    private final int nights;

    Booking(int nights) { this.nights = nights; }

    Booking withNights(int nights) {          // parent returns Booking
        return new Booking(nights);
    }

    int getNights() { return nights; }
}

class RoomBooking extends Booking {
    private final double nightly;

    RoomBooking(int nights, double nightly) {
        super(nights);
        this.nightly = nightly;
    }

    @Override
    RoomBooking withNights(int nights) {      // narrower return, still an override
        return new RoomBooking(nights, nightly);
    }

    double getNightly() { return nightly; }
}

RoomBooking r = new RoomBooking(2, 90.0).withNights(4);   // no cast here
System.out.println(r.getNights());        // 4
System.out.println(r.getNightly());       // 90.0

Booking b = new RoomBooking(2, 90.0).withNights(4);       // parent type, parent view
System.out.println(b.getClass().getSimpleName());          // RoomBooking
